def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    active = {}

    # Connect diagonally aligned 1s.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) != abs(dc):
                continue
            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            for k in range(abs(dr) + 1):
                r, c = r1 + k * sr, c1 + k * sc
                if grid[r][c] == 6:
                    active[(r, c)] = (1 if dr * dc > 0 else -1)
                elif grid[r][c] == bg:
                    out[r][c] = 1

    # A 6 on a connecting segment draws a perpendicular diagonal.
    for (r0, c0), slope_type in active.items():
        for r in range(h):
            if slope_type == 1:       # connector slopes down-right
                c = r0 + c0 - r      # perpendicular: constant row+column
            else:                     # connector slopes down-left
                c = c0 + (r - r0)    # perpendicular: constant column-row
            if 0 <= c < w and grid[r][c] == bg:
                out[r][c] = 6

    return out
